def minMaxWeight(n: int, edges: List[List[int]], threshold: int) -> int:
    def canReachNode0(maxWeight):
        graph = [[] for _ in range(n)]
        for u, v, w in edges:
            if w <= maxWeight:
                graph[v].append(u)  # Allow node u to reach v

        reachable = [False] * n
        reachable[0] = True
        queue = [0]
        while queue:
            node = queue.pop(0)
            for neighbor in graph[node]:
                if not reachable[neighbor]:
                    reachable[neighbor] = True
                    queue.append(neighbor)

        return all(reachable)

    def countOutgoingEdges(maxWeight):
        graph = [[] for _ in range(n)]
        for u, v, w in edges:
            if w <= maxWeight:
                graph[u].append((v, w))

        outgoingCount = [0] * n
        for u in range(n):
            for v, _ in graph[u]:
                outgoingCount[u] += 1
                if outgoingCount[u] > threshold:
                    return False
        return True

    left, right = 1, 10**6
    result = -1
    while left <= right:
        mid = (left + right) // 2
        if canReachNode0(mid) and countOutgoingEdges(mid):
            result = mid
            right = mid - 1
        else:
            left = mid + 1

    return result

from typing import List

def minCost(n: int, cost: List[List[int]]) -> int:
    # Initialize a DP array to store minimum costs for each house painted in each color.
    dp = [[float('inf')] * 3 for _ in range(n)]
    # Fill the first house costs directly from the cost array.
    for j in range(3):
        dp[0][j] = cost[0][j]

    # Fill the DP table for houses 1 to n-1.
    for i in range(1, n):
        for j in range(3):
            for k in range(3):
                if k != j:
                    dp[i][j] = min(dp[i][j], dp[i - 1][k] + cost[i][j])

    # Now handling the equidistant constraint by analyzing two halves.
    min_cost = float('inf')
    for j in range(3):  # Choose a color for the first half last house
        for k in range(3):  # Choose a color for the second half last house
            if j != k:
                # Combine the costs without violating adjacent and equidistant rules
                cost_first_half = dp[n//2 - 1][j]  # Up to the midpoint
                cost_second_half = dp[n - 1][k]  # Last house in the second half
                min_cost = min(min_cost, cost_first_half + cost_second_half)

    return min_cost

from typing import List


def countMentions(numberOfUsers: int, events: List[List[str]]) -> List[int]:
    mentions = [0] * numberOfUsers
    online_status = [True] * numberOfUsers
    event_list = []

    # Process events and track online status
    for event in events:
        event_type, timestamp, *details = event
        timestamp = int(timestamp)
        if event_type == "OFFLINE":
            user_id = int(details[0])
            online_status[user_id] = False
            event_list.append((timestamp + 60, user_id, 'ONLINE'))  # Schedule coming back online
        elif event_type == "MESSAGE":
            event_list.append((timestamp, 'MESSAGE', details[0]))

    # Sort events by timestamp
    event_list.sort(key=lambda x: x[0])

    # Process sorted events
    for event in event_list:
        if event[1] == 'MESSAGE':
            mentions_string = event[2]
            if mentions_string == "ALL":
                for user_id in range(numberOfUsers):
                    mentions[user_id] += 1
            elif mentions_string == "HERE":
                for user_id in range(numberOfUsers):
                    if online_status[user_id]:
                        mentions[user_id] += 1
            else:
                for mention in mentions_string.split():
                    if mention.startswith("id"):
                        user_id = int(mention[2:])
                        mentions[user_id] += 1
        else:
            # Handle online event
            _, user_id, status = event
            if status == 'ONLINE':
                online_status[user_id] = True

    return mentions
